import{_ as t,o as i,c as o,a2 as n}from"./chunks/framework.DPTp4bo7.js";const g=JSON.parse('{"title":"Repository of Survey Suggestions","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/repository-of-survey-suggestions"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/repository-of-survey-suggestions"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/repository-of-survey-suggestions"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/repository-of-survey-suggestions"}]]},"headers":[],"relativePath":"repository-of-survey-suggestions.md","filePath":"logistics/src/page-pY03IOJsZdm5I2dQLe59Yi.md"}'),s={name:"repository-of-survey-suggestions.md"};function a(r,e,l,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><span class="logistics-source-anchor" id="问卷提建议存储处" aria-hidden="true"></span><h1 id="repository-of-survey-suggestions" tabindex="-1">Repository of Survey Suggestions <a class="header-anchor" href="#repository-of-survey-suggestions" aria-label="Permalink to &quot;Repository of Survey Suggestions&quot;">​</a></h1><blockquote><p>Source page ID: <code>pY03IOJsZdm5I2dQLe59Yi</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pY03IOJsZdm5I2dQLe59Yi" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Many people forget the feedback they meant to put in surveys until after submitting. To reduce that, write suggestions here and copy them when filling in a survey.</p><details><summary>jnk</summary><p>Revise the development overview: add an option under skills and talents to exclude normal-attack skill upgrades. Add multi-selection and one-click etching for Essences. Add a blueprint plaza where all shared blueprints are public and freely browsable, letting people sift through the muck for gold.</p></details><details><summary>言</summary><p><strong>Bug reports</strong></p><p>The 1s stall after 8 switches between multi-input reactions needs fixing.</p><p>Depot Unloader output falls far short of round-robin servicing and needs fixing; Depot Loaders work reasonably well.</p><p>Automatic Planting Units swallow items during harvesting. See the video: [Endfield] In Case You Didn&#39;t Know Automatic Harvesters Secretly Eat Potatoes: <a href="https://www.bilibili.com/video/BV1PLJ86VEnr?vd_source=bf73afe506171ce1f2c1a4732d9d4bde" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1PLJ86VEnr?vd_source=bf73afe506171ce1f2c1a4732d9d4bde</a></p><p><strong>Suggestions</strong></p><p>Blueprints only save within 50m, preventing all main-base conduits being saved at once and making sharing difficult. Pipe limits further increase conduit demand. Increase the range to 80m to cover the main base.</p><p>It is easy to delete conduits connected externally while modifying a factory. Add conduit locking, or ideally manual locking for all facilities.</p><p>Improve conduit interactions in bird&#39;s-eye mode: allow connections from the overhead view and display them clearly. Based on my building experience, one draft solution—or a precise expression of what I mean—is to let selected conduits show/hide their connections, with multiple connections visible simultaneously.</p><p>Display pipe-logistics-component, facility and pipe limits in real time. I do not oppose reasonable limits: requiring designers to optimize underlying architecture and reduce constrained components is a distinctive factory-game challenge. But failing to show them live is terrible. Discovering only at final assembly that a design cannot be built because of these limits is an awful experience.</p><p>Using Xiranite Pylons inside industrial land can unexpectedly disconnect external power lines. A line originally attached to the PAC remains attached when the PAC moves, but a Xiranite Pylon may replace it as the external connection. Deleting that pylon during rebuilding disconnects the external wire. Although not a bug, this logic is cumbersome and should be improved.</p><p>Too few blueprints can be saved, with no categorization or sorting controls.</p><p>Add fluid/gas bus lines and storage, or another way to prevent fluid/gas resources constraining layouts. Such limits are common in real life and other factory games, but in Endfield I mainly feel they unnecessarily tie layouts in knots. Area and pipe-component constraints already encourage optimization. Removing this restriction would greatly free deeper factory players&#39; creativity, while helping casual players avoid the hell of copying layouts with incorrect external fluid/gas connections.</p></details><details><summary>Expanded content</summary></details></div>',1)])])}const h=t(s,[["render",a]]);export{g as __pageData,h as default};
